package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	SKU   string  `json:"sku"`
}

// sanitizeOrderBy attempts to prevent injection in ORDER BY clauses
// by checking against allowed column names
func sanitizeOrderBy(input string) string {
	allowed := map[string]bool{"id": true, "name": true, "price": true, "sku": true}
	parts := strings.Split(input, " ")
	if len(parts) >= 1 && allowed[strings.ToLower(parts[0])] {
		if len(parts) == 2 && (strings.ToUpper(parts[1]) == "ASC" || strings.ToUpper(parts[1]) == "DESC") {
			return parts[0] + " " + strings.ToUpper(parts[1])
		}
		return parts[0]
	}
	return "id"
}

// handleSearch processes product search with category filter
func handleSearch(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := sanitizeOrderBy(r.URL.Query().Get("sort"))

	// Build query with parameterized price filters
	baseQuery := "SELECT id, name, price, sku FROM products WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if category != "" {
		// Category uses a pre-defined enum check
		validCategories := []string{"electronics", "clothing", "food", "toys"}
		catValid := false
		for _, vc := range validCategories {
			if strings.EqualFold(category, vc) {
				catValid = true
				break
			}
		}
		if catValid {
			baseQuery += fmt.Sprintf(" AND category = $%d", argIdx)
			args = append(args, category)
			argIdx++
		}
	}

	if minPrice != "" {
		baseQuery += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, minPrice)
		argIdx++
	}

	if maxPrice != "" {
		baseQuery += fmt.Sprintf(" AND price <= $%d", argIdx)
		args = append(args, maxPrice)
		argIdx++
	}

	// NOTE: sortBy is validated above via sanitizeOrderBy
	baseQuery += " ORDER BY " + sortBy + " LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		http.Error(w, "query error", http.StatusInternalServerError)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// handleProductDetail fetches a single product by ID
func handleProductDetail(w http.ResponseWriter, r *http.Request) {
	prodID := r.URL.Query().Get("id")
	if prodID == "" {
		http.Error(w, "missing id", http.StatusBadRequest)
		return
	}

	// Direct string interpolation - vulnerable to SQL injection
	query := fmt.Sprintf("SELECT id, name, price, sku FROM products WHERE id = %s", prodID)

	var p Product
	err := db.QueryRow(query).Scan(&p.ID, &p.Name, &p.Price, &p.SKU)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

func main() {
	http.HandleFunc("/api/search", handleSearch)
	http.HandleFunc("/api/product", handleProductDetail)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
